mapper.select:
SELECT r.id, r.shop_id, r.user_id, r.rating, r.content, r.images, r.is_ai_generated, r.like_count, r.status, r.created_at, u.nickname AS user_nickname FROM review r LEFT JOIN user u ON r.user_id = u.id WHERE r.shop_id = #{shopId} AND r.status = 1
AND r.content LIKE CONCAT('%', #{keyword}, '%')
ORDER BY r.like_count DESC, r.rating DESC, r.created_at DESC LIMIT #{limit}

mapper.update:
UPDATE review
SET like_count = like_count + 1
WHERE id = #{id}

UPDATE review
SET like_count = CASE WHEN like_count > 0 THEN like_count - 1 ELSE 0 END
WHERE id = #{id}

mapper.select:
SELECT COUNT(*)
FROM review
WHERE status = 1
  AND created_at >= #{startDate}
  AND created_at <= #{endDate}

mapper.update:
UPDATE review
SET status = 0
WHERE id = #{id}
